package org.securemail.client.ecosystem;
import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.file.*;
import java.security.*;
import java.time.Clock;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.client.*;
import org.securemail.client.crypto.Identity;
import org.securemail.client.storage.*;
import org.securemail.ecosystem.protocol.IdentityProtocol;
class MailRecoveryIdentity600Test {
 @TempDir Path root;String prior,account;ClientConfig config;byte[] recoveryPublic;Path backup,exported;static final char[] PASSWORD="public synthetic recovery Mail password".toCharArray(),EXPORT="public synthetic recovery export password".toCharArray();
 @BeforeEach void setup()throws Exception{prior=System.getProperty("aegis.profile");System.setProperty("aegis.profile",root.resolve("app").toString());config=ClientConfig.load(AppPaths.config());config.save(AppPaths.config());backup=root.resolve("identity.aegis-backup");exported=root.resolve("independent.aer6");try(var mail=open(config.storagePath());var recovery=MailRecoveryKey600.loadOrCreate(mail)){mail.bindNickname("raven");account=mail.identity().userId();recoveryPublic=recovery.publicKey();mail.exportIdentity(backup);recovery.exportEncrypted(exported,EXPORT,account);}Files.createDirectories(config.storagePath().resolve("archive"));Files.writeString(config.storagePath().resolve("archive/opaque.enc"),"public synthetic archive ciphertext");}
 @AfterEach void restore(){if(prior==null)System.clearProperty("aegis.profile");else System.setProperty("aegis.profile",prior);}
 LocalStore open(Path path)throws Exception{return new LocalStore(path,PASSWORD,Clock.systemUTC(),config.maxCiphertext(),config.maxLocalStorage());}
 Map<String,String> hashes(Path path)throws Exception{var found=new TreeMap<String,String>();try(var files=Files.walk(path)){for(Path f:files.filter(Files::isRegularFile).toList())found.put(path.relativize(f).toString(),HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(f))));}return found;}
 @Test void existingIdentityPrivateCopyAndIndependentKeyLeaveOriginalBytesUntouched()throws Exception{var before=hashes(config.storagePath());Path privatePath;try(var holder=MailRecoveryIdentity600.openExisting(config,PASSWORD,account,()->false);var recovery=MailRecoveryKey600.loadExisting(holder.mail()).orElseThrow()){assertEquals(account,holder.mail().identity().userId());assertArrayEquals(recoveryPublic,recovery.publicKey());privatePath=holder.mail().root();assertNotEquals(config.storagePath(),privatePath);assertFalse(Files.exists(privatePath.resolve("archive")));assertEquals(before,hashes(config.storagePath()));}assertFalse(Files.exists(privatePath));assertEquals(before,hashes(config.storagePath()));assertEquals(config.storagePath(),ClientConfig.load(AppPaths.config()).storagePath());}
 @Test void realEncryptedIdentityRestoreVerifiesBeforeConfigSwitchAndKeepsOldProfile()throws Exception{var old=hashes(config.storagePath());byte[] source=Files.readAllBytes(backup);Path target;try(var holder=MailRecoveryIdentity600.restoreBackup(config,backup,PASSWORD,account,()->false)){target=holder.mail().root();assertEquals(target,ClientConfig.load(AppPaths.config()).storagePath());assertNotEquals(config.storagePath(),target);assertEquals(account,holder.mail().identity().userId());assertEquals("raven",holder.mail().nickname());assertTrue(MailRecoveryKey600.loadExisting(holder.mail()).isEmpty());assertFalse(Files.exists(target.resolve("archive")));}assertTrue(Files.isRegularFile(target.resolve("state.vault")));assertEquals(old,hashes(config.storagePath()));assertArrayEquals(source,Files.readAllBytes(backup));try(var verified=open(target)){assertEquals(account,verified.identity().userId());}}
 @Test void wrongPasswordWrongAccountAndCancellationCannotChangeConfigOrOriginal()throws Exception{var old=hashes(config.storagePath());byte[] configBytes=Files.readAllBytes(AppPaths.config());assertThrows(Exception.class,()->MailRecoveryIdentity600.restoreBackup(config,backup,"public wrong password".toCharArray(),account,()->false));assertThrows(GeneralSecurityException.class,()->MailRecoveryIdentity600.restoreBackup(config,backup,PASSWORD,Identity.create().userId(),()->false));assertThrows(InterruptedIOException.class,()->MailRecoveryIdentity600.restoreBackup(config,backup,PASSWORD,account,()->true));assertThrows(GeneralSecurityException.class,()->MailRecoveryIdentity600.openExisting(config,PASSWORD,Identity.create().userId(),()->false));assertArrayEquals(configBytes,Files.readAllBytes(AppPaths.config()));assertEquals(old,hashes(config.storagePath()));try(var files=Files.list(AppPaths.root().resolve("mail600/recovered-identities"))){assertEquals(0,files.count());}}
 @Test void importedRecoveryProducesOnlyTwoFixedPublicProofsAndRejectsWrongFiles()throws Exception{try(var holder=MailRecoveryIdentity600.restoreBackup(config,backup,PASSWORD,account,()->false);var independent=MailRecoveryKey600.importEncrypted(exported,EXPORT,account)){assertTrue(MailRecoveryKey600.loadExisting(holder.mail()).isEmpty());var keys=KeyPairGenerator.getInstance("Ed25519");var device=keys.generateKeyPair();var server=keys.generateKeyPair();var request=new IdentityProtocol.DeviceRecovery(IdentityProtocol.id(server.getPublic().getEncoded()),account,device.getPublic().getEncoded(),IdentityProtocol.nonce(),System.currentTimeMillis()+240000);var answer=MailPairing600.decodeDeviceRecoveryResult(MailPairing600.deviceRecoveryResult(holder.approve(request,independent)));assertArrayEquals(recoveryPublic,answer.recoveryPublic());assertTrue(IdentityProtocol.verify(answer.accountPublic(),IdentityProtocol.deviceRecoveryBytes(request),answer.accountProof()));assertTrue(IdentityProtocol.verify(answer.recoveryPublic(),IdentityProtocol.deviceRecoveryBytes(request),answer.recoveryProof()));assertFalse(IdentityProtocol.verify(answer.accountPublic(),"not a recovery".getBytes(),answer.accountProof()));assertTrue(MailRecoveryKey600.loadExisting(holder.mail()).isEmpty());var expired=new IdentityProtocol.DeviceRecovery(request.audience,account,device.getPublic().getEncoded(),IdentityProtocol.nonce(),System.currentTimeMillis()-1);assertThrows(GeneralSecurityException.class,()->holder.approve(expired,independent));}assertThrows(GeneralSecurityException.class,()->MailRecoveryKey600.importEncrypted(exported,"public wrong export password".toCharArray(),account));assertThrows(IOException.class,()->MailRecoveryKey600.importEncrypted(exported,EXPORT,Identity.create().userId()));}
 @Test void symlinkInputsAreRejectedWithoutFollowingOrPublishing()throws Exception{Path link=root.resolve("backup-link");Files.createSymbolicLink(link,backup);assertThrows(IOException.class,()->MailRecoveryIdentity600.restoreBackup(config,link,PASSWORD,account,()->false));Path linkRoot=root.resolve("profile-link");Files.createSymbolicLink(linkRoot,config.storagePath());assertThrows(IOException.class,()->MailRecoveryIdentity600.openExisting(config.withStorage(linkRoot),PASSWORD,account,()->false));assertEquals(config.storagePath(),ClientConfig.load(AppPaths.config()).storagePath());}
}
